do $$
declare
  v_owner  uuid := 'c9827bd9-1614-4c51-bd25-762d3ae0cac0';
  v_client uuid := (select c.id from dma.clients c join platform.tenants t on t.id=c.tenant_id where t.slug='herman-legacy-digital' and c.slug='venuewise');
  v_5star  uuid := (select c.id from dma.clients c join platform.tenants t on t.id=c.tenant_id where t.slug='herman-legacy-digital' and c.slug='5-star-sports-media');
  v_ten    uuid := (select id from platform.tenants where slug='herman-legacy-digital');
  v_off    uuid := (select o.id from dma.offerings o where o.client_id=v_client and o.name='HomeHuddle');
  s_multi  uuid := (select id from dma.market_segments where offering_id=v_off and name='Multi-sport families');
  s_hockey uuid := (select id from dma.market_segments where offering_id=v_off and name='Travel/competitive hockey families');
  s_athlete uuid := (select id from dma.market_segments where offering_id=v_off and name='Multi-athlete sports households');
  src_cmp uuid; src_buf uuid;
begin
  if v_off is null then raise exception 'HomeHuddle offering not found'; end if;
  insert into dma.research_sources (tenant_id,client_id,offering_id,title,url,publisher,source_type,method,published_on,accessed_on,credibility,summary,created_by) values
   (v_ten,v_client,v_off,'Search: best app to combine multiple sports schedules (who ranks)','https://www.google.com/search?q=best+app+to+combine+multiple+sports+team+schedules','Web search observation','web','web_search','2026-08-08','2026-08-08','low','Orgo positions "built exclusively for sports parents managing multiple kids/teams"; SportsCal ($47/yr), TeamSnap, Schedule Caddie also rank. Strong comparison-intent competition; HomeHuddle absent.',v_owner),
   (v_ten,v_client,v_off,'Buffalo NY youth/travel hockey ecosystem','https://myhockeyrankings.com/association-info?a=1499','MyHockeyRankings / tournament orgs','web','web_search','2025-01-01','2026-08-08','medium','Real, organized WNY hockey ecosystem: Buffalo Youth Hockey Assoc, Cazenovia Park, Nickel City Hockey, Battle of Buffalo, Buffalo Backyard Classic; Northtown Center & RiverWorks facilities.',v_owner)
  on conflict do nothing;
  select id into src_cmp from dma.research_sources where url='https://www.google.com/search?q=best+app+to+combine+multiple+sports+team+schedules';
  select id into src_buf from dma.research_sources where url='https://myhockeyrankings.com/association-info?a=1499';
  update dma.discovery_intents set confidence='medium' where offering_id=v_off and intent_phrase='sports family calendar Buffalo / WNY';

  insert into dma.search_opportunities (tenant_id,client_id,offering_id,segment_id,query_or_topic,search_intent,demand_level,demand_evidence,difficulty_level,commercial_relevance,content_type,execution_arm,priority,source_id,confidence,provenance,verification,created_by)
  select v_ten,v_client,v_off,d.seg,d.q,d.si::dma.search_intent,d.dem::dma.magnitude,d.de,d.dif::dma.magnitude,d.com::dma.magnitude,d.ct::dma.content_type,d.arm::dma.execution_arm,
         dma.compute_search_priority(d.com::dma.magnitude,d.dem::dma.magnitude,d.dif::dma.magnitude),
         d.src,d.conf::dma.confidence,'ai_inferred','needs_review',v_owner
  from (values
    (s_multi,'HomeHuddle (brand)','navigational','unknown','Nascent brand; own the branded SERP cheaply.','low','high','product_page','homehuddle_website',src_cmp,'medium'),
    (s_multi,'best app to combine multiple sports schedules','comparison','unknown','Many "best apps" listicles + direct competitors (Orgo/SportsCal) rank; content supply implies real demand. Volume not measured.','medium','high','comparison_page','comparison_page',src_cmp,'medium'),
    (s_hockey,'Buffalo / WNY travel hockey family schedule','solution_aware','unknown','Organized WNY hockey ecosystem (assocs, tournaments, rinks); local competition thinner.','low','medium','local_page','homehuddle_website',src_buf,'medium'),
    (s_multi,'multi-sport family calendar','solution_aware','unknown','Direct competitors (Orgo, TeamSnap, Schedule Caddie) target this; high difficulty. Volume not measured.','high','high','landing_page','homehuddle_website',src_cmp,'medium'),
    (s_multi,'family sports calendar app','solution_aware','unknown','Heavily contested by team apps + general calendars.','high','high','landing_page','homehuddle_website',src_cmp,'low'),
    (s_hockey,'hockey family schedule app','solution_aware','unknown','Hockey team apps (TeamLinkt, Mad Puck, TeamSnap) rank; high difficulty.','high','high','landing_page','homehuddle_website',src_cmp,'medium'),
    (s_multi,'manage multiple kids sports schedules','problem_aware','unknown','Abundant how-to/listicle content = real problem-aware demand. Volume not measured.','medium','medium','guide','five_star_media',src_cmp,'medium'),
    (s_hockey,'how do families manage multiple travel hockey schedules','informational','unknown','TeamSnap + hockey guides produce this content (demand signal). Strong 5-Star editorial fit.','medium','medium','editorial_story','five_star_media',src_buf,'medium'),
    (s_multi,'sync team app to family calendar','solution_aware','unknown','How-to demand (Schedule Caddie/Briefly content).','medium','medium','faq','homehuddle_website',src_cmp,'low'),
    (s_athlete,'one calendar for multiple kids activities','problem_aware','unknown','Multi-child coordination; overlaps general + sports.','medium','medium','landing_page','homehuddle_website',src_cmp,'low')
  ) as d(seg,q,si,dem,de,dif,com,ct,arm,src,conf)
  on conflict do nothing;

  insert into dma.website_specs (tenant_id,client_id,offering_id,segment_id,page_type,title,target_segment,search_intent,primary_problem,value_proposition,primary_cta,seo_target,tracking_objective,execution_arm,decision,rationale,source_id,confidence,provenance,verification,created_by) values
   (v_ten,v_client,v_off,s_multi,'landing_page','One family calendar for all your kids'' sports','Multi-sport families','solution_aware','Multiple team apps + group texts; no single family view.','HomeHuddle auto-syncs GameChanger/TeamSnap/LeagueApps into one family calendar.','Start free trial','multi-sport family calendar / combine sports schedules','Paid subscriber acquisition','homehuddle_website','build','Core solution-aware intent on the exact wedge. High difficulty — flagship landing page + supporting content.',src_cmp,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multi,'landing_page','Multi-child sports scheduling','Multi-athlete households','problem_aware',null,null,'Start free trial','manage multiple kids sports schedules','Paid subscriber acquisition','homehuddle_website','combine','Same solution cluster as the flagship landing — combine to avoid thin duplicate pages.',src_cmp,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multi,'comparison_page','HomeHuddle vs Orgo vs TeamSnap','Multi-sport families','comparison','Which app actually aggregates a family''s many teams?','HomeHuddle is sports-native family aggregation (not per-team, not a generic calendar).','See the comparison','best app to combine sports schedules / Orgo alternative','Paid subscriber acquisition','comparison_page','build','Comparison intent has clear demand; Orgo is the direct threat. Medium difficulty, high commercial.',src_cmp,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_hockey,'landing_page','The family calendar for hockey families','Travel/competitive hockey families','solution_aware','Weekend tournaments, long travel, missed updates are costly.','One place for every practice, game and tournament across the family.','Start free trial','hockey family schedule app','Paid subscriber acquisition','homehuddle_website','build','Acute segment; pairs with the Buffalo beachhead and 5-Star hockey editorial.',src_buf,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_hockey,'local_page','HomeHuddle for Buffalo & WNY travel hockey families','Travel hockey families (Buffalo/WNY)','transactional','Coordinating a WNY travel-hockey season across rinks and tournaments.','Built for sports families — now serving Buffalo/WNY travel hockey.','Start free trial (Buffalo)','Buffalo travel hockey family schedule','Paid subscriber acquisition (local beachhead)','homehuddle_website','build','Evidence upgraded: real WNY hockey ecosystem + thinner local competition; HomeHuddle already live in Buffalo. Low difficulty.',src_buf,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multi,'structured_data','HomeHuddle structured data (SoftwareApplication) + FAQ','Multi-sport families','navigational','Answer engines/AI cannot confidently surface HomeHuddle.','Machine-readable product facts + FAQ.','Start free trial','HomeHuddle / family sports calendar','AI/brand SERP surfacing','homehuddle_website','build','Cheap, high-leverage: improves AI-readiness and the branded SERP. Pairs with the site build.',null,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multi,'product_page','HomeHuddle product page (own the branded SERP)','Multi-sport families','navigational','Brand is new; branded searches must resolve to a strong page.','Clear product story + trial CTA.','Start free trial','HomeHuddle','Paid subscriber acquisition','homehuddle_website','build','Highest-priority, lowest-difficulty: own the branded SERP before scaling demand-gen.',src_cmp,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_off,s_multi,'landing_page','Generic intent-specific page bucket','Multi-sport families','solution_aware',null,null,null,'various long-tail','Paid subscriber acquisition','homehuddle_website','defer','Reject mass-produced thin pages; specific BUILD pages above cover the priority intents. Revisit long-tail expansion after DMA-05 volume data.',null,'low','ai_inferred','needs_review',v_owner)
  on conflict do nothing;

  insert into dma.media_opportunities (tenant_id,client_id,producer_client_id,offering_id,topic,search_intent,audience_value,product_relevance,content_format,cta_context,source_id,confidence,provenance,verification,created_by) values
   (v_ten,v_client,v_5star,v_off,'How families manage multiple travel hockey schedules (guide + video)','informational','Genuinely useful playbook for hockey families (planning, carpools, tournament logistics).','Contextually introduces HomeHuddle as the tool that aggregates it — not a disguised ad.','editorial_story','Soft "try HomeHuddle" at article end',src_buf,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_5star,v_off,'Buffalo travel-hockey season survival guide (local editorial)','informational','Local WNY value: rinks, tournaments (Battle of Buffalo, Backyard Classic), season tips.','Local HomeHuddle beachhead exposure alongside genuine local coverage.','local_page','Local trial CTA',src_buf,'medium','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_5star,v_off,'A multi-sport family week: day-in-the-life (video)','problem_aware','Relatable multi-sport family story with real logistics value.','Shows the coordination problem HomeHuddle solves.','video','Contextual product intro',src_cmp,'low','ai_inferred','needs_review',v_owner),
   (v_ten,v_client,v_5star,v_off,'Youth sports tournament weekend: the planning checklist','problem_aware','Practical checklist content sports parents seek.','HomeHuddle as the living version of the checklist.','guide','Contextual CTA',src_cmp,'low','ai_inferred','needs_review',v_owner)
  on conflict do nothing;
end $$;